package edu.smartstudy.quiz;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="quiz_attempts")public class QuizAttempt{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="quiz_id",nullable=false)private Long quizId;@Column(name="student_id",nullable=false)private Long studentId;@Column(nullable=false)private int score;@Column(name="total_questions",nullable=false)private int totalQuestions;@Column(name="answers_json",nullable=false,columnDefinition="MEDIUMTEXT")private String answersJson;@Column(name="submitted_at",insertable=false,updatable=false)private Instant submittedAt;protected QuizAttempt(){}public QuizAttempt(Long quizId,Long studentId,int score,int total,String answers){this.quizId=quizId;this.studentId=studentId;this.score=score;totalQuestions=total;answersJson=answers;}public Long getId(){return id;}public Long getQuizId(){return quizId;}public int getScore(){return score;}public int getTotalQuestions(){return totalQuestions;}public Instant getSubmittedAt(){return submittedAt;}}
